head.b:skin:
/* Theme variables */
:root {
    --highcolor: #e95454;
    --fontcolor: #1f2937;
    --headercolor: #111827;
    --mutedcolor: #6b7280;
    --surfacecolor: #ffffff;
}

/* Base page styling */
body {
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    font-family: "Open Sans", sans-serif;
    font-optical-sizing: auto;
    font-size: 17px;
    font-weight: 400;
    font-style: normal;
    font-variation-settings: "wdth" 100;
    line-height: 1.7;
    color: var(--fontcolor);
    background-color: var(--surfacecolor);
}

pre {
    margin: 0;
    padding: 0;
    tab-size: 4;
    white-space: pre;
}

/* Link and typography styles */
a {
    text-decoration: none;
    color: inherit;
    transition: color 0.2s;
}

a:hover {
    color: var(--highcolor);
}

h1, h2, h3, h4, h5, h6 {
    font-family: 'Merriweather', serif;
    margin: 0;
    padding: 0;
    color: var(--headercolor);
    line-height: 1.3;
    letter-spacing: -0.02em;
}

#blog-pager a {
    font-size: 24px;
    font-weight: 700;
    color: var(--highcolor);
}

h1,h2 {
    font-size: 32px;
    font-weight: 700;
}

h3 {
    font-size: 24px;
    font-weight: 700;
}

h4 {
    font-size: 20px;
    font-weight: 700;
}

/* Main layout containers */
header, #social-media, main, footer {
    margin-left: auto;
    margin-right: auto;
    width: min(1104px, 100%);
    max-width: 1104px;
}

header {
    font-family: 'Merriweather', serif;
    font-size: 36px;
    justify-content: center;
    text-align: center;
    color: var(--highcolor);
    border-bottom: 4px solid var(--highcolor);
}

main {
    display: flex;
    gap: 40px;
    min-height: 100vh;
}

section {
    width: 728px;
}

article {
    margin-bottom: 50px;
}

.post-date {
    margin: 8px 0 18px;
    font-size: 12px;
    line-height: 1.4;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--mutedcolor);
}

.post-date .post-date-icon {
    color: var(--highcolor);
    margin-right: 6px;
}

/* Sidebar and widget styles */
aside {
    width: 336px;
    font-size: 15px;
    color: var(--fontcolor);
}

.side-bar {
    margin: 0 0 15px;
}

.side-bar h3 {
    margin: 0 0 14px;
}

aside ul {
    margin: 0;
}

.download-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin: 0 0 18px;
    padding: 10px 18px;
    border: 1px solid var(--highcolor);
    border-radius: 999px;
    background: linear-gradient(135deg, rgba(233, 84, 84, 0.12), rgba(233, 84, 84, 0.04));
    color: var(--highcolor);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    transition: all 0.25s ease;
    box-shadow: 0 6px 18px rgba(233, 84, 84, 0.12);
}

.download-link:hover {
    color: var(--surfacecolor);
    background: linear-gradient(135deg, var(--highcolor), #d54a4a);
    box-shadow: 0 10px 24px rgba(233, 84, 84, 0.22);
    transform: translateY(-1px);
}

/* Social media icons */
#social-media {
    display: flex;
    justify-content: flex-end;
    margin-bottom: 30px;
}

#social-media > span {
    display: flex;
    gap: 10px;
}

#social-media a:hover {
    color: #fff;
}

.fa {
    padding: 7px;
    width: 60px;
    box-sizing: border-box;
    text-align: center;
    text-decoration: none;
    color: var(--surfacecolor);
}

.fa svg {
    fill: currentColor;
    margin: auto;
}

/* Footer and search field */
footer {
    padding: 25px 0;
    margin-top: auto;
    text-align: center;
    font-size: 15px;
    color: var(--headercolor);
    border-top: 1px solid var(--highcolor);
}

#usearch {
    display: block;
    width: 100%;
    box-sizing: border-box;
    margin: 0;
    padding: 12px 16px;
    font-size: 15px;
    border: 2px solid var(--highcolor);
    border-radius: 8px;
    background: var(--surfacecolor);
    color: var(--fontcolor);
    font-family: inherit;
    line-height: 1.4;
    transition: all 0.3s ease;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
}

#uform {
    display: block;
    width: 100%;
    margin: 0;
    padding: 0;
}

#usearch:focus {
    outline: none;
    border-color: var(--highcolor);
    box-shadow: 0 0 0 3px rgba(245, 106, 106, 0.15);
}

#usearch::placeholder {
    color: #999;
}

#usearch:hover {
    border-color: #d94f4f;
}

#PopularPosts1 ul li {
    margin-bottom: 10px;
}

/* Responsive adjustments */
@media (min-width: 811px) {
    aside {
        position: sticky;
        top: 24px;
        align-self: flex-start;
        max-height: calc(100vh - 48px);
        overflow-y: auto;
    }
}

@media (max-width: 810px) {
    body {
        margin: 10px;
    }

    header, #social-media, main, footer {
        width: 100%;
    }

    #social-media {
        width: 100%;
    }

    main {
        flex-direction: column;
        gap: 30px;
    }

    section, aside {
        width: 100%;
    }

    .fa {
        padding: 7px;
        width: 38px;
    }
}

/* Code and syntax highlighting */
.codeSection {
    font-size:16px;
    padding:0px;
    margin:0px;
}

.fileName {
    color:#c586c0;
    margin-bottom:5px;
    font-weight:600;
    letter-spacing:0.03em;
}

.code {
    line-height:1.6;
    padding:15px;
    overflow:auto;
    color:#e6edf3;
    background-color:#0d1117;
    border-left:5px solid #30363d;
    border-radius:4px;
}

pre {
    margin:0px;
    padding:0px;
    font-family:Consolas, "Courier New", monospace;
    -moz-tab-size:4;
    -o-tab-size:4;
    tab-size:4;
}

.lI {
    color:#e6edf3;
}

.kC {
    color:#ff7b72;
}

.cC {
    color:#8b949e;
}

.qC { 
    color:#a5d6ff;
}

.pC {
    color:#c9d1d9;
}

.iPC {
    color:#79c0ff;
}

.bC {
    color:#c9d1d9;
}

.iBC {
    color:#79c0ff;
}
